 StableId commit_reception(const StableId& actor,PoliticalAssumeOfficeReception command,Integer request){common.state().metadata.player_actor_id=actor;auto old=reception_state;auto x=context();auto q=take(preview_political_office_reception(x,actor,command));auto id=take(apply_political_office_reception_in_candidate(common,reception_state,x,actor,command,q));historical_players[id]=actor;check(take(political_office_reception_new_player_source(old,reception_state,actor,political_office_reception_command,common.tick()))==id,"before/after selects only actual newly written reception");auto result=std::make_shared<CommitResult>();result->ok=true;result->kind=political_office_reception_command;result->tick=common.tick();result->revision=++common.state().identity.revision;result->result_id=take(common.next_id("result"));common.state().request_sequences.set(actor,request);common.state().results.insert(actor+":"+std::to_string(request),result);common.state().history.push_back({result->tick,result->kind,actor,result->result_id,{}});take(bind_political_office_reception_player_result(common,reception_state,id,actor,request,*result,[&](const CommitResult&,const StableId& source){return source==id;}));return id;}
