int main(){try{
 ReceptionReceiptFixture f;f.install();auto first=f.commit_reception("candidate",f.request(),2);f.change("leader");auto second=f.commit_reception("leader",{{"city","chief",2,"leader"},"counter","candidate",first},2);f.change("candidate");auto last=f.commit_reception("candidate",{{"city","chief",3,"candidate"},"counter","leader",second},3);check(f.valid().ok,"three actual role transfers preserve original Office history and separate result bindings");auto common=f.common.state();auto state=f.reception_state;auto retained=*f.common.state().results.find("candidate:3");f.common.state().results={};f.common.state().results.insert("candidate:3",retained);f.common.state().history.erase(f.common.state().history.begin(),f.common.state().history.end()-1);check(f.valid().ok,"first retained result validates by exact permanent source");f.reception_state.assignments.erase(last);f.common.state().facts.erase(last);f.common.state().roles.find("public.counter")->actor_id="leader";check(!f.valid().ok,"delete new source and reset Role cannot reuse older same-tick result");f.common.state()=common;f.reception_state=state;f.common.state().results={};f.common.state().history.clear();check(f.valid().ok,"all cache may crop without erasing actual bindings");f.reception_state.assignments.find(last)->player_receipt=f.reception_state.assignments.find(first)->player_receipt;check(!f.valid().ok,"old source cannot donate result after cache crop");f.common.state()=common;f.reception_state=state;f.reception_state.assignments.find(last)->player_receipt.reset();auto copied=*retained;check(!bind_political_office_reception_player_result(f.common,f.reception_state,last,"candidate",3,copied,[](const auto&,const auto&){return true;}).ok,"copied result is not original cached object");check(!f.reception_state.assignments.find(last)->player_receipt,"failed binder leaves source unbound");
 CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);auto saved=state;take(visit_political_office_reception_checkpoint(writer,saved));take(writer.finish());const auto& input=bytes;CodecVisitor reader(input);PoliticalOfficeReceptionState decoded;take(visit_political_office_reception_checkpoint(reader,decoded));take(reader.finish());check(compare_boundary(encode_political_office_reception_state(state),encode_political_office_reception_state(decoded)).exact(),"independent typed tail preserves original role and result sources");auto command=f.request();check(compare_boundary(encode_political_office_reception_command(command),encode_political_office_reception_command(take(decode_political_office_reception_command(encode_political_office_reception_command(command))))).exact(),"command codec freezes only actual authority and prior role");
 ReceptionReceiptFixture late;late.install();late.common.state().metadata.player_actor_id="candidate";late.common.state().next_instance_id=INT64_MAX-1;auto x=late.context();auto quote=take(preview_political_office_reception(x,"candidate",late.request()));const auto before=late.common.state();const auto old=late.reception_state;auto token=take(late.common.begin_savepoint());take(apply_political_office_reception_in_candidate(late.common,late.reception_state,x,"candidate",late.request(),quote));check(!late.common.next_id("result").ok,"actual result allocation fails after Role and source writes");take(late.common.rollback_savepoint(token));late.reception_state=old;check(late.common.state().roles.find("public.counter")->actor_id=="leader"&&late.common.state().facts.order()==before.facts.order()&&late.common.state().next_instance_id==before.next_instance_id&&late.reception_state.assignments.empty(),"outer savepoint restores Role/source/counter on late actual-result failure");
 std::cout<<checks<<" public reception receipt assertions; source test only\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
